mapper.select:
select
c2.c_name as pprBusinessUnitName,
c3.c_name as pprReserveCpyName,
mn.*,
u1.U_Name as pprProjectManagerName,
u2.U_Name as pprProjectLeaderName,
u3.U_Name as pprEngineerName,
u4.U_Name as pprEngineerLeaderName,
d1.d_name as pprManagerUnitName,
d2.d_name as pprManagerDepName
from Pre_Project_Reserve_Change mn
left join sys_department d1 on d1.d_id=mn.ppr_manager_unit
left join sys_department d2 on d2.d_id=mn.ppr_Manager_Dep
left join sys_company c2 on c2.c_id=mn.ppr_business_unit
left join sys_company c3 on c3.c_id=mn.ppr_Reserve_cpy
left join SYS_User u1 on u1.u_id=mn.ppr_project_manager
left join SYS_User u2 on u2.u_id=mn.ppr_project_leader
left join SYS_User u3 on u3.u_id=mn.ppr_engineer
left join SYS_User u4 on u4.u_id=mn.ppr_engineer_leader

    
        and mn.state != 3
    
    
        and mn.ppr_compose=#{params.pprCompose}
    
    
        and mn.ppr_model=#{params.pprModel}
    
    
        and mn.ppr_shape=#{params.pprShape}
    
    
        and mn.ppr_classify=#{params.pprClassify}
    
    
        and mn.ppr_approval=#{params.pprApproval}
    
    
        and mn.ppr_construction_year=#{params.pprConstructionYear}
    
    
        and mn.ppr_work_stage=#{params.pprWorkStage}
    
    
        and mn.ppr_Reserve_status=#{params.pprReserveStatus}
    
    
        and mn.ppr_Reserve_stage=#{params.pprReserveStage}
    
    
        and mn.state=#{params.state}
    
    
        and mn.ppr_manager_unit=#{params.pprManagerUnit}
    
    
        and mn.ppr_business_unit=#{params.pprBusinessUnit}
    
    
        and mn.ppr_id=#{params.pprId}
    
    
        and mn.ppr_Reserve_cpy=#{params.pprReserveCpy}
    
    
        and INSTR(mn.create_uname,#{params.createUname})
    
    
        and INSTR(mn.ppr_name,#{params.pprName})
    
    
        and INSTR(mn.ppr_manager_dep,#{params.pprManagerDep})
    
    
        and INSTR(d2.d_name,#{params.pprManagerDepName})
    
    
        and INSTR(d1.d_name,#{params.pprManagerUnitName})
    
    
        
            
                and likeCname(#{params.pprBusinessUnitName},c2.C_Id)=true
            
            
                and INSTR(c2.c_name,#{params.pprBusinessUnitName})
            
        
    
    
        
            
                and likeCname(#{params.pprReserveCpyName},c3.C_Id)=true
            
            
                and INSTR(c3.c_name,#{params.pprReserveCpyName})
            
        
    


    
        order by ISNULL(mn.${params.sortFiled}),mn.${params.sortFiled} ${params.sortType}
    
    
        order by ISNULL(${params.sortSideFiled}),${params.sortSideFiled} ${params.sortType}
    
    
        order by mn.Create_Time desc
